"""the GnssSpoofing signal, generated by the gnss engine while a scenario plays

scg plays a scenario into a file as fast as the engine goes, so these runs are the only
place the suite asks the real engine for samples. they read the rinex file that ships
under assets/rinex, the engine moves its ephemerides to the time it is asked for
"""

import json

import pytest

from helpers.binaries import ROOT
from helpers.wavio import read_iq

EPHEMERIS = ROOT / "assets" / "rinex" / "BRDC00IGS_R_20211700000_01D_MN.rnx"
SAMPLE_RATE = 1000000

EXIT_OK = 0
EXIT_INVALID = 1


def make_scenario(file_name, sample_rate=SAMPLE_RATE):
    """one spoofer from 0.25 s to 1 s of a 1.25 s scenario, its trajectory ends at 0.25 s"""
    return {
        "duration": 1.25,
        "outputs": [
            {
                "name": "f0",
                "type": "File",
                "fileName": str(file_name),
                "nChannels": 1,
                "samplerate": sample_rate,
                "center": 1575420000.0,
            }
        ],
        "signals": [
            {
                "name": "spoof",
                "type": "GnssSpoofing",
                "signal": "GPS_L1CA",
                "startTime": "2026-10-14T12:00:00Z",
                "ephemerisFile": str(EPHEMERIS),
                "trajectory": [
                    {"t": 0.0, "latitude": 47.4927, "longitude": 19.0158, "altitude": 120.0},
                    {"t": 0.25, "latitude": 47.4928, "longitude": 19.0159, "altitude": 120.0},
                ],
            }
        ],
        "events": [
            {
                "signal": "spoof",
                "output": "f0",
                "channel": 0,
                "frequency": 1575420000.0,
                "amplitude": 1.0,
                "start": 0.25,
                "end": 1.0,
            }
        ],
    }


def write_scenario(tmp_path, scenario, name="gnss.json"):
    path = tmp_path / name
    path.write_text(json.dumps(scenario, indent=4), encoding="utf-8")
    return path


def lint(build, path):
    result = build.run("scglint", ["scenario", path])
    return result.returncode, result.stdout + result.stderr


def power(samples):
    return sum(abs(s) ** 2 for s in samples) / len(samples)


def test_a_gnss_scenario_is_accepted(build, tmp_path):
    path = write_scenario(tmp_path, make_scenario(tmp_path / "out.wav"))
    code, output = lint(build, path)
    assert code == EXIT_OK, output


@pytest.mark.parametrize("t", [0.1, -0.1], ids=["late", "negative"])
def test_a_trajectory_not_starting_at_zero_is_reported(build, tmp_path, t):
    scenario = make_scenario(tmp_path / "out.wav")
    scenario["signals"][0]["trajectory"][0]["t"] = t
    code, output = lint(build, write_scenario(tmp_path, scenario))
    assert code == EXIT_INVALID, output
    assert "the first waypoint has to be at t = 0" in output, output


def test_a_trajectory_going_back_in_time_is_reported(build, tmp_path):
    scenario = make_scenario(tmp_path / "out.wav")
    scenario["signals"][0]["trajectory"][1]["t"] = 0.0
    code, output = lint(build, write_scenario(tmp_path, scenario))
    assert code == EXIT_INVALID, output
    assert "trajectory[1]: time does not advance" in output, output


def test_a_rate_of_a_fraction_of_a_khz_is_reported(build, tmp_path):
    scenario = make_scenario(tmp_path / "out.wav", sample_rate=1000500)
    code, output = lint(build, write_scenario(tmp_path, scenario))
    assert code == EXIT_INVALID, output
    assert "needs an output sample rate of whole khz" in output, output


def test_an_unknown_signal_is_reported(build, tmp_path):
    scenario = make_scenario(tmp_path / "out.wav")
    scenario["signals"][0]["signal"] = "GPS_L1C"
    code, output = lint(build, write_scenario(tmp_path, scenario))
    assert code != EXIT_OK, output
    assert 'unknown enum value "GPS_L1C"' in output, output


def test_scg_generates_the_spoofer_for_its_event_only(build, tmp_path):
    """silence around the event, and signal through all of it, the part after the last
    waypoint included, where the position holds"""
    out = tmp_path / "out.wav"
    path = write_scenario(tmp_path, make_scenario(out))
    result = build.run("scg", ["-s", path], timeout=300, cwd=tmp_path)
    assert result.returncode == 0, result.stdout + result.stderr

    sample_rate, channels = read_iq(out)
    assert sample_rate == SAMPLE_RATE
    samples = channels[0]
    assert len(samples) == int(1.25 * SAMPLE_RATE)

    quarter = SAMPLE_RATE // 4
    powers = [power(samples[i * quarter:(i + 1) * quarter:25]) for i in range(5)]
    assert powers[0] == 0.0, powers
    assert all(p > 0.0 for p in powers[1:4]), powers
    assert powers[4] == 0.0, powers
